-- Q3428: Fund-to-Government-Wide Reconciliation [medium/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Added to the change in fund balances as a positive adjustment","Subtracted from the change in fund balances in the reconciliation","Not a reconciling item between fund and government-wide statements","Reported separately as an other financing use in the reconciliation"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): Under GASB 34, depreciation is an expense on government-wide statements but does not appear as an expenditure in governmental funds because capital assets are not reported in funds. The reconciliation subtracts depreciation to convert the change in fund balances to the change in net position. Wrong (A): Depreciation reduces net position; adding it would move the reconciliation in the wrong direction. Wrong (C): Depreciation is a significant reconciling item because it exists only on government-wide statements. Wrong (D): Depreciation is not an other financing use; it is an operating expense adjustment in the reconciliation.$EXPL$
WHERE id = 3428;

-- Q4832: Business Combinations [medium/L2]
-- Issues: #1, #3
UPDATE questions SET
